// Android only: extracts the APK assets/data/ tree into
// <filesDir>/aseprite/data/, where app::ResourceFinder looks for it
// (HOME/XDG_CONFIG_HOME = filesDir are set by laf's android_main(),
// ADR 0002). assets/data.manifest is generated by the Gradle task
// GenerateDataAssets: the first line is "sha256 <hash>", then one path
// (relative to assets/data/) per line.
//
// This file must be part of the final shared library (see
// src/CMakeLists.txt), not of app-lib: os::android_pre_main is a weak
// reference in laf and wouldn't pull it from a static library.

#ifdef HAVE_CONFIG_H
  #include "config.h"
#endif

#include "os/android/android_app.h"

#include <android/asset_manager.h>
#include <android/log.h>
#include <game-activity/native_app_glue/android_native_app_glue.h>

#include <chrono>
#include <filesystem>
#include <fstream>
#include <sstream>
#include <string>
#include <system_error>

#define ALOG_TAG "Aseprite"
#define ALOGI(...) __android_log_print(ANDROID_LOG_INFO, ALOG_TAG, __VA_ARGS__)
#define ALOGE(...) __android_log_print(ANDROID_LOG_ERROR, ALOG_TAG, __VA_ARGS__)

namespace fs = std::filesystem;

namespace {

bool read_asset(AAssetManager* am, const std::string& name, std::string& out)
{
  AAsset* asset = AAssetManager_open(am, name.c_str(), AASSET_MODE_STREAMING);
  if (!asset)
    return false;
  out.clear();
  char buf[16 * 1024];
  int n = 0;
  while ((n = AAsset_read(asset, buf, sizeof(buf))) > 0)
    out.append(buf, n);
  AAsset_close(asset);
  return n == 0;
}

bool extract_asset(AAssetManager* am, const std::string& name, const fs::path& dst)
{
  AAsset* asset = AAssetManager_open(am, name.c_str(), AASSET_MODE_STREAMING);
  if (!asset) {
    ALOGE("cannot open asset %s", name.c_str());
    return false;
  }

  std::error_code ec;
  fs::create_directories(dst.parent_path(), ec);
  if (ec) {
    ALOGE("cannot create %s: %s", dst.parent_path().c_str(), ec.message().c_str());
    AAsset_close(asset);
    return false;
  }

  std::ofstream f(dst, std::ios::binary | std::ios::trunc);
  char buf[16 * 1024];
  int n = 0;
  while (f && (n = AAsset_read(asset, buf, sizeof(buf))) > 0)
    f.write(buf, n);
  AAsset_close(asset);
  f.close();
  if (!f || n < 0) {
    ALOGE("cannot write %s", dst.c_str());
    return false;
  }
  return true;
}

std::string read_file(const fs::path& path)
{
  std::ifstream f(path, std::ios::binary);
  std::stringstream ss;
  ss << f.rdbuf();
  return ss.str();
}

std::string trim_eol(std::string s)
{
  while (!s.empty() && (s.back() == '\n' || s.back() == '\r'))
    s.pop_back();
  return s;
}

} // namespace

namespace os {

void android_pre_main(::android_app* app)
{
  const auto t0 = std::chrono::steady_clock::now();

  const char* filesDir = app->activity->internalDataPath;
  AAssetManager* am = app->activity->assetManager;
  if (!filesDir || !am) {
    ALOGE("no filesDir or AssetManager, data/ not extracted");
    return;
  }

  std::string manifest;
  if (!read_asset(am, "data.manifest", manifest)) {
    ALOGE("assets/data.manifest not found in the APK");
    return;
  }

  std::istringstream lines(manifest);
  std::string header;
  std::getline(lines, header);
  header = trim_eol(header);
  if (header.compare(0, 7, "sha256 ") != 0) {
    ALOGE("invalid data.manifest header '%s'", header.c_str());
    return;
  }

  const fs::path base = fs::path(filesDir) / "aseprite";
  const fs::path dataDir = base / "data";
  const fs::path stampFile = dataDir / ".stamp";

  if (fs::exists(stampFile) && trim_eol(read_file(stampFile)) == header) {
    ALOGI("data up to date (%s)", dataDir.c_str());
    return;
  }

  // Extract to data.new/ and swap it in, so an interrupted extraction
  // never leaves a half-filled data/ with a valid stamp.
  const fs::path tmpDir = base / "data.new";
  std::error_code ec;
  fs::remove_all(tmpDir, ec);
  fs::create_directories(tmpDir, ec);
  if (ec) {
    ALOGE("cannot create %s: %s", tmpDir.c_str(), ec.message().c_str());
    return;
  }

  int count = 0;
  std::string rel;
  while (std::getline(lines, rel)) {
    rel = trim_eol(rel);
    if (rel.empty())
      continue;
    if (!extract_asset(am, "data/" + rel, tmpDir / rel)) {
      ALOGE("extraction failed after %d files", count);
      return;
    }
    ++count;
  }

  {
    std::ofstream stamp(tmpDir / ".stamp", std::ios::trunc);
    stamp << header << '\n';
    if (!stamp) {
      ALOGE("cannot write the stamp in %s", tmpDir.c_str());
      return;
    }
  }

  fs::remove_all(dataDir, ec);
  fs::rename(tmpDir, dataDir, ec);
  if (ec) {
    ALOGE("cannot move %s to %s: %s", tmpDir.c_str(), dataDir.c_str(), ec.message().c_str());
    return;
  }

  const auto ms = std::chrono::duration_cast<std::chrono::milliseconds>(
                    std::chrono::steady_clock::now() - t0)
                    .count();
  ALOGI("extracted %d files in %lld ms (%s)", count, static_cast<long long>(ms), dataDir.c_str());
}

} // namespace os
